def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg for _ in range(w)] for _ in range(h)]
    seen = set()
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            for y, x in q:
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == v:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            ys = [y for y, x in cells]
            xs = [x for y, x in cells]
            y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
            area = (y1 - y0 + 1) * (x1 - x0 + 1)
            if area >= 6 and len(cells) >= 4 and len(cells) / area >= 0.5:
                for y in range(y0, y1 + 1):
                    for x in range(x0, x1 + 1):
                        out[y][x] = v
    return out
